import { Controller, Get, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 엑셀 파일은 별도 라이브러리 없이 Excel에서 열리는 CSV(UTF-8 BOM)로 내려준다 (값의 출처: 개발 담당자 결정).
const CSV_BOM = '\uFEFF';
const FILE_NAME = 'hr-records.csv';
const CONTENT_TYPE = 'text/csv; charset=utf-8';

function cell(value: unknown): string {
  let text = value === null || value === undefined ? '' : String(value);
  if (/^[=+\-@]/.test(text)) {
    text = "'" + text;
  }
  return '"' + text.replace(/"/g, '""') + '"';
}

@Controller('api/v1')
export class FnSfr01401Controller {
  @Get('/hr-records/export')
  async exportHrRecords(@Req() req: Request) {
    const user = currentUser(req);
    user.require('인사 담당자', '시스템 관리자');
    const query = checks.queryOf(req.query);
    const departmentRaw = query['departmentId'];
    let departmentId: string | null = null;
    if (departmentRaw !== undefined && departmentRaw !== null && String(departmentRaw) !== '') {
      if (!/^\d+$/.test(String(departmentRaw))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '소속 부서 ID는 숫자여야 합니다.');
      }
      departmentId = String(departmentRaw);
    }
    const name = query['name'] === undefined || query['name'] === null ? '' : String(query['name']);
    const employeeNo = query['employeeNo'] === undefined || query['employeeNo'] === null ? '' : String(query['employeeNo']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT e.employee_no AS "employeeNo",
                e.name AS "name",
                d.name AS "departmentName",
                h.position_name AS "positionName",
                h.employment_status AS "employmentStatus",
                to_char(h.hire_date, 'YYYY-MM-DD') AS "hireDate",
                to_char(h.retirement_date, 'YYYY-MM-DD') AS "retirementDate"
           FROM hr_record h
           JOIN employee e ON e.employee_id = h.employee_id
           LEFT JOIN department d ON d.department_id = h.department_id
          WHERE (CAST(:departmentId AS bigint) IS NULL OR h.department_id = CAST(:departmentId AS bigint))
            AND (:name = '' OR strpos(e.name, :name) > 0)
            AND (:employeeNo = '' OR strpos(e.employee_no, :employeeNo) > 0)
          ORDER BY e.employee_no`,
        { departmentId, name, employeeNo },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'NO_DATA_TO_EXPORT', '내려받을 데이터가 없습니다.');
      }
      const header = ['사번', '성명', '소속 부서', '직위', '재직 구분', '입사일', '퇴직일'];
      const lines = [header.map(cell).join(',')];
      for (const row of rows) {
        lines.push(
          [
            row.employeeNo,
            row.name,
            row.departmentName,
            row.positionName,
            row.employmentStatus,
            row.hireDate,
            row.retirementDate,
          ]
            .map(cell)
            .join(','),
        );
      }
      return {
        file: {
          fileName: FILE_NAME,
          contentType: CONTENT_TYPE,
          content: CSV_BOM + lines.join('\r\n'),
        },
      };
    });
  }
}

