import { useState } from 'react';
import {
  Band,
  Badge,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  Pager,
  RefName,
  Select,
  TextInput,
  call,
  useData,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;

export default function FnSfr01401Page({ role, notify }: PageProps) {
  const [draft, setDraft] = useState<Row>({});
  const [applied, setApplied] = useState<Row>({});
  const [pageNo, setPageNo] = useState(0);
  const [exporting, setExporting] = useState(false);
  const [exportForm, setExportForm] = useState<Row>({});

  const { data, error, loading } = useData<Page>(
    () => call<Page>('GET', '/hr-records', role, undefined, { ...applied, page: pageNo, size: SIZE }),
    [applied, pageNo, role],
  );

  function search() {
    setPageNo(0);
    setApplied({ ...draft });
  }

  function reset() {
    setDraft({});
    setApplied({});
    setPageNo(0);
  }

  function openExport() {
    setExportForm({ departmentId: draft.departmentId ?? '' });
    setExporting(true);
  }

  async function doExport() {
    const res = await call<{ file: { fileName: string; contentType: string; content: string } }>(
      'GET',
      '/hr-records/export',
      role,
      undefined,
      {
        departmentId: exportForm.departmentId,
        name: exportForm.name,
        employeeNo: exportForm.employeeNo,
      },
    );
    const blob = new Blob([res.file.content], { type: res.file.contentType });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = res.file.fileName;
    link.click();
    URL.revokeObjectURL(url);
    setExporting(false);
    notify('엑셀 파일을 내려받았습니다.');
  }

  const rows = data ? data.items : [];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>조회 건수</h2>
        <div><Num value={data ? data.total : 0} /></div>
      </section>
      <section className="box span-12">
        <h2>인사정보 현황</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="재직 구분">
            <Select
              value={draft.employmentStatus}
              onChange={(v) => setDraft({ ...draft, employmentStatus: v })}
              options={[
                ['재직', '재직'],
                ['휴직', '휴직'],
                ['단축근무', '단축근무'],
                ['퇴직', '퇴직'],
              ]}
            />
          </Field>
          <Field label="소속 부서">
            <LookupSelect
              table="department"
              role={role}
              value={draft.departmentId}
              onChange={(v) => setDraft({ ...draft, departmentId: v })}
            />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openExport}>엑셀 다운로드</button>
        </Band>
        {error ? <p>{error}</p> : null}
        <DataTable
          columns={[
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'departmentId', label: '소속 부서', render: (r) => <RefName table="department" role={role} value={r.departmentId} /> },
            { key: 'positionName', label: '직위' },
            { key: 'employmentStatus', label: '재직 구분', render: (r) => <Badge value={r.employmentStatus} /> },
            { key: 'hireDate', label: '입사일', render: (r) => <DateText value={r.hireDate} /> },
            { key: 'retirementDate', label: '퇴직일', render: (r) => <DateText value={r.retirementDate} /> },
          ]}
          rows={rows}
          empty={loading ? '불러오는 중입니다.' : '조회 결과가 없습니다.'}
        />
        <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
      </section>
      {exporting ? (
        <Drawer title="엑셀 다운로드" onClose={() => setExporting(false)}>
          <Form onSubmit={doExport} submit="내려받기">
            <Field label="소속 부서">
              <LookupSelect
                table="department"
                role={role}
                value={exportForm.departmentId}
                onChange={(v) => setExportForm({ ...exportForm, departmentId: v })}
              />
            </Field>
            <Field label="성명 검색">
              <TextInput
                value={exportForm.name}
                onChange={(v) => setExportForm({ ...exportForm, name: v })}
              />
            </Field>
            <Field label="사번 검색">
              <TextInput
                value={exportForm.employeeNo}
                onChange={(v) => setExportForm({ ...exportForm, employeeNo: v })}
              />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
